from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    """Return x modulo 2: 0 for even, 1 for odd. Negative inputs give 0 or 1."""
    return x % 2


def parities(xs: list[int], max_workers: int | None = None) -> list[int]:
    """Return the parity of each element of xs, computed in a thread pool.

    The result is in input order. max_workers is passed to the thread pool
    (None means the executor default). The result must not depend on it.
    """
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        return list(pool.map(parity, xs))


def test_parity_basic() -> None:
    assert parity(0) == 0
    assert parity(7) == 1
    assert parity(-3) == 1


def test_parities_order() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2]) == [1, 0]


def test_parities_independent_of_worker_count() -> None:
    xs = list(range(100))
    expected = [x % 2 for x in xs]
    for workers in (1, 2, 8):
        assert parities(xs, max_workers=workers) == expected
